//! 📏️ Literal IFC2x3 field bounds pay actual borrowed traversal backing.
use super::*;
fn text(value:&str,bound:&mut artifact::NativeEncodingBound<'_,'_>)->Result<(),ValueError>{bound.repeated(value.len(),16)?;bound.add(96)}
fn arguments(roots:&[Part21Value],bound:&mut artifact::NativeEncodingBound<'_,'_>)->Result<(),ValueError>{
 let mut pending=bound.allocate_frontier::<std::slice::Iter<'_,Part21Value>>(1)?;pending.push(roots.iter());let mut nodes=0usize;
 while !pending.is_empty(){let Some(value)=pending.last_mut().unwrap().next()else{pending.pop();continue};nodes=nodes.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"IFC2x3 bound node count overflow"))?;bound.check_rows(nodes)?;bound.add(384)?;
 let children=match value{Part21Value::Str(value)|Part21Value::Enum(value)=>{text(value,bound)?;&[][..]},Part21Value::Real(decimal)=>{text(&decimal.coefficient,bound)?;&[][..]},Part21Value::List(values)=>values.as_slice(),Part21Value::Typed{name,items}=>{text(name,bound)?;items.as_slice()},_=>&[]};if !children.is_empty(){bound.push_frontier(&mut pending,children.iter())?;}bound.checkpoint()?;
 }Ok(())
}
pub(super) fn preflight(value:&Ifc2x3Snapshot,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
 value.admit_sqlite_values(control,SqliteSnapshotPhase::EncodeNative)?;let mut bound=artifact::NativeEncodingBound::file_only(control)?;bound.add(4096)?;text(&value.schema,&mut bound)?;
 if let Some(edm)=&value.edm_preamble{for value in [&edm.producer,&edm.module,&edm.creation_date,&edm.host,&edm.database,&edm.database_version,&edm.database_creation_date,&edm.schema,&edm.model,&edm.model_creation_date,&edm.header_model,&edm.header_model_creation_date,&edm.user,&edm.group,&edm.license,&edm.options]{text(value,&mut bound)?;}}
 for values in [&value.document.header.file_description,&value.document.header.file_name,&value.document.header.file_schema]{arguments(values,&mut bound)?;}
 bound.check_rows(value.document.instances.len())?;for instance in &value.document.instances{bound.add(192)?;bound.check_rows(instance.entities.len())?;for(name,values)in &instance.entities{bound.add(128)?;text(name,&mut bound)?;arguments(values,&mut bound)?;}bound.checkpoint()?;}bound.finish()
}

//! 📏️ IFC4 native bounds pay traversal storage while forecasting owned field encodings.
use super::*;
use semio_framework_os_kernel::sqlite_snapshot::artifact;
fn text(value:&str,bound:&mut artifact::NativeEncodingBound<'_,'_>)->Result<(),ValueError>{bound.repeated(value.len(),16)?;bound.add(96)}
fn rows(count:&mut usize,size:usize,bound:&mut artifact::NativeEncodingBound<'_,'_>)->Result<(),ValueError>{*count=count.checked_add(size).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"IFC4 native row census overflow"))?;bound.check_rows(*count)}
fn arguments(roots:&[IfcValue],bound:&mut artifact::NativeEncodingBound<'_,'_>,count:&mut usize)->Result<(),ValueError>{
 rows(count,roots.len(),bound)?;let mut pending=bound.allocate_frontier::<std::slice::Iter<'_,IfcValue>>(1)?;pending.push(roots.iter());
 while !pending.is_empty(){let Some(value)=pending.last_mut().unwrap().next()else{pending.pop();continue};rows(count,1,bound)?;bound.add(256)?;
 let children=match value{IfcValue::String(value)|IfcValue::Enum(value)=>{text(value,bound)?;&[][..]},IfcValue::Aggregate(values)=>values.as_slice(),IfcValue::TypedValue{name,items}=>{text(name,bound)?;items.as_slice()},_=>&[]};
 rows(count,children.len(),bound)?;if !children.is_empty(){bound.push_frontier(&mut pending,children.iter())?;}bound.checkpoint()?;
 }Ok(())
}
pub(super) fn preflight(value:&IfcSnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
 value.admit_sqlite_values(control,SqliteSnapshotPhase::EncodeNative)?;let mut bound=artifact::NativeEncodingBound::file_only(control)?;let mut count=0;rows(&mut count,2,&mut bound)?;bound.add(4096)?;text(&value.schema,&mut bound)?;
 for values in [&value.header.file_description,&value.header.file_name,&value.header.file_schema]{arguments(values,&mut bound,&mut count)?;}
 rows(&mut count,value.entities.len(),&mut bound)?;for entity in &value.entities{bound.add(256)?;text(&entity.name,&mut bound)?;arguments(&entity.args,&mut bound,&mut count)?;
 rows(&mut count,entity.complex.len(),&mut bound)?;for part in &entity.complex{bound.add(128)?;text(&part.name,&mut bound)?;arguments(&part.args,&mut bound,&mut count)?;}bound.checkpoint()?;}bound.finish()
}

//! 📏️ Borrowed STEP owned-record bounds pay concrete traversal frontiers.
use super::*;
fn text(value:&str,bound:&mut artifact::NativeEncodingBound<'_,'_>)->Result<(),ValueError>{bound.repeated(value.len(),16)?;bound.add(96)}
fn arguments(roots:&[StepValue],bound:&mut artifact::NativeEncodingBound<'_,'_>)->Result<(),ValueError>{
 let mut pending=bound.allocate_frontier::<std::slice::Iter<'_,StepValue>>(1)?;pending.push(roots.iter());let mut nodes=0usize;
 while !pending.is_empty(){let Some(value)=pending.last_mut().unwrap().next()else{pending.pop();continue};nodes=nodes.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"STEP bound node count overflow"))?;bound.check_rows(nodes)?;bound.add(256)?;
 let children=match value{StepValue::String(value)|StepValue::Enum(value)=>{text(value,bound)?;&[][..]},StepValue::Aggregate(values)=>values.as_slice(),StepValue::TypedValue{type_name,value}=>{text(type_name,bound)?;std::slice::from_ref(value.as_ref())},_=>&[]};if !children.is_empty(){bound.push_frontier(&mut pending,children.iter())?;}bound.checkpoint()?;
 }Ok(())
}
pub(super) fn preflight(value:&StepSnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
 value.admit_sqlite_values(control,SqliteSnapshotPhase::EncodeNative)?;let mut bound=artifact::NativeEncodingBound::file_only(control)?;bound.add(4096)?;text(&value.schema,&mut bound)?;let header=&value.header;let name=&header.file_name;
 for value in [&header.file_description.implementation_level,&name.name,&name.timestamp,&name.preprocessor_version,&name.originating_system,&name.authorization]{text(value,&mut bound)?;}
 for list in [&header.file_description.description,&name.author,&name.organization,&header.file_schema.schemas]{bound.check_rows(list.len())?;for value in list{text(value,&mut bound)?;bound.checkpoint()?;}}
 bound.check_rows(value.entities.len())?;for entity in &value.entities{bound.add(256)?;text(&entity.name,&mut bound)?;arguments(&entity.args,&mut bound)?;bound.check_rows(entity.complex.len())?;for part in &entity.complex{bound.add(128)?;text(&part.name,&mut bound)?;arguments(&part.args,&mut bound)?;}bound.checkpoint()?;}bound.finish()
}
